definitions.rule:
.faq-header h1 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
    background: linear-gradient(135deg, var(--accent-primary), var(--accent-secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.category-title {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
    color: var(--text-primary);
}

.category-title {
    font-size: clamp(1rem, 3.5cqi + 0.3rem, 1.5rem);
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: clamp(0.5rem, 1.5cqi, 0.875rem);
}

.category-title {
    font-size: 1.3rem;
    font-weight: 600;
    color: var(--accent-primary, #00d4ff);
    margin-bottom: 0.75rem;
    text-align: center;
}

.category-title {
    font-size: 1.75rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: var(--spacing-lg);
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
}

.faq-item {
    margin-bottom: 1rem;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(0, 255, 255, 0.1);
    border-radius: 12px;
    overflow: hidden;
    backdrop-filter: blur(12px);
    transition: all 0.3s ease;
}

.faq-item:hover {
    background: rgba(255, 255, 255, 0.05);
    border-color: rgba(0, 255, 255, 0.3);
    transform: translateY(-2px);
    box-shadow: 0 4px 20px rgba(0, 255, 255, 0.1);
}

.faq-item.expanded .faq-answer {
    max-height: 1000px;
    padding: var(--spacing-lg);
    border: 1px solid var(--glass-border);
    border-top: none;
}

.faq-question {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.25rem 1.5rem;
    background: transparent;
    border: none;
    color: var(--text-primary);
    font-size: 1.1rem;
    font-weight: 500;
    text-align: left;
    cursor: pointer;
    transition: all 0.3s ease;
}

.faq-question {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--spacing-lg);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    cursor: pointer;
    transition: all var(--transition-base);
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary);
}

.toggle-icon {
    font-size: 1.5rem;
    font-weight: 300;
    color: var(--accent-primary);
    transition: transform 0.3s ease;
    min-width: 30px;
    text-align: center;
}

.faq-answer {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-answer code {
    background: rgba(0, 255, 255, 0.1);
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-family: 'Courier New', monospace;
    font-size: 0.9em;
    color: var(--accent-primary);
}

.faq-answer a {
    color: var(--accent-primary);
    text-decoration: none;
    border-bottom: 1px solid transparent;
    transition: border-color 0.2s ease;
}

.faq-answer {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-slow), padding var(--transition-slow);
    padding: 0 var(--spacing-lg);
    background: rgba(10, 14, 39, 0.6);
    border-radius: 0 0 var(--radius-md) var(--radius-md);
}

.comparison-table {
    width: 100%;
    margin: 1.5rem 0;
    border-collapse: collapse;
    background: rgba(255, 255, 255, 0.02);
    border-radius: 8px;
    overflow: hidden;
}

.comparison-table th {
    background: rgba(0, 255, 255, 0.1);
    padding: 1rem;
    text-align: left;
    font-weight: 600;
    color: var(--text-primary);
    border-bottom: 2px solid rgba(0, 255, 255, 0.2);
}

.comparison-table td {
    padding: 1rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    color: var(--text-secondary);
}

.faq-footer {
    text-align: center;
    margin-top: 4rem;
    padding-top: 2rem;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-link {
    color: var(--accent-primary);
    text-decoration: none;
    margin: 0 0.5rem;
    transition: opacity 0.2s ease;
}

.footer-link {
    color: var(--future-accent);
    text-decoration: none;
    font-weight: 500;
    transition: color 0.3s ease;
}

.footer-link {
    color: var(--text-secondary);
    text-decoration: none;
    font-size: 0.875rem;
    transition: all var(--transition-base);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: var(--radius-sm);
}

.main-nav {
    background: rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    padding: 15px 0;
    position: sticky;
    top: 0;
    z-index: 100;
}

.main-nav {
    position: sticky;
    top: 0;
    left: 0;
    right: 0;
    z-index: 1000;
    background: rgba(10, 14, 39, 0.75);
    backdrop-filter: blur(20px) saturate(180%);
    -webkit-backdrop-filter: blur(20px) saturate(180%);
    border-bottom: 1px solid rgba(0, 212, 255, 0.2);
    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37),
                inset 0 1px 0 0 rgba(255, 255, 255, 0.05);
    transition: all var(--transition-base);
    animation: navSlideDown 0.6s ease-out;
}

.main-nav.scrolled {
    background: rgba(10, 14, 39, 0.9);
    backdrop-filter: blur(30px) saturate(200%);
    -webkit-backdrop-filter: blur(30px) saturate(200%);
    box-shadow: 0 8px 40px 0 rgba(0, 0, 0, 0.5),
                inset 0 1px 0 0 rgba(255, 255, 255, 0.1),
                0 0 60px rgba(0, 212, 255, 0.15);
    border-bottom: 1px solid rgba(0, 212, 255, 0.3);
}

.nav-links a {
    color: var(--text-secondary);
    text-decoration: none;
    font-weight: 500;
    transition: color 0.3s ease;
}

.nav-links a {
    color: var(--text-secondary);
    text-decoration: none;
    font-weight: 500;
    font-size: 0.95rem;
    transition: all var(--transition-base);
    position: relative;
    padding: 0.5rem 0;
}

.nav-links a::before {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 0;
    height: 2px;
    background: linear-gradient(90deg, transparent, var(--accent-primary), transparent);
    transition: width var(--transition-base);
}

.nav-links a {
        padding: 0.75rem 0.5rem;
        min-height: 44px;
        display: flex;
        align-items: center;
    }

.nav-links {
        flex-wrap: wrap;
        justify-content: center;
        gap: 0.5rem;
        width: 100%;
    }

.future-hero {
    text-align: center;
    padding: 80px 20px;
    max-width: 1000px;
    margin: 0 auto;
}

.future-hero h1 {
    font-size: 3.5rem;
    margin-bottom: 20px;
    background: linear-gradient(135deg, var(--future-primary) 0%, var(--future-secondary) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.vision-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 30px;
    max-width: 1400px;
    margin: 0 auto;
    padding: 40px 20px;
}

.vision-card {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 20px;
    padding: 35px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    transition: all 0.4s ease;
    position: relative;
    overflow: hidden;
}

.vision-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 4px;
    background: linear-gradient(90deg, var(--future-primary), var(--future-secondary));
    transform: scaleX(0);
    transition: transform 0.4s ease;
}

.vision-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 40px rgba(102, 126, 234, 0.3);
    border-color: var(--future-primary);
}

.vision-icon {
    background: linear-gradient(135deg, #ec4899, #f472b6);
    color: white;
    width: 60px;
    height: 60px;
    border-radius: var(--radius-md);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.75rem;
    margin-bottom: var(--spacing-md);
}

.timeline-line {
    position: absolute;
    left: 50%;
    top: 0;
    bottom: 0;
    width: 2px;
    background: linear-gradient(180deg, var(--future-primary), var(--future-accent));
    transform: translateX(-50%);
}

.timeline-item::before {
    content: '';
    position: absolute;
    left: calc(-1 * var(--spacing-xl) - 6px);
    top: 0;
    width: 14px;
    height: 14px;
    background: var(--accent-primary);
    border-radius: 50%;
    box-shadow: 0 0 10px var(--accent-primary);
}

.timeline-content {
    width: 45%;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 15px;
    padding: 25px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    transition: all 0.3s ease;
}

.timeline-marker {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    width: 20px;
    height: 20px;
    background: var(--future-primary);
    border: 4px solid rgba(30, 30, 46, 1);
    border-radius: 50%;
    z-index: 10;
}

.stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
    margin: 40px 0;
}

.stat-card {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 15px;
    padding: 25px;
    text-align: center;
    border: 1px solid rgba(255, 255, 255, 0.1);
}

.stat-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: var(--space-lg);
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: var(--radius-md);
    min-width: 120px;
}

.stat-label {
    font-size: 0.95rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.stat-label {
    font-size: 0.875rem;
    color: var(--text-secondary);
    margin-top: var(--space-xs);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.feature-list li {
    padding: 15px 20px;
    margin-bottom: 10px;
    background: rgba(255, 255, 255, 0.03);
    border-left: 3px solid var(--future-primary);
    border-radius: 8px;
    transition: all 0.3s ease;
}

.feature-list li {
    color: rgba(255, 255, 255, 0.7);
    font-size: 14px;
    padding: 6px 0 6px 20px;
    position: relative;
}

.feature-list li::before {
    content: "✓";
    position: absolute;
    left: 0;
    color: var(--future-success);
    font-weight: 700;
}

.feature-list li {
    padding: 0.75rem 0;
    padding-left: 1.5rem;
    position: relative;
    color: rgba(255, 255, 255, 0.85);
    line-height: 1.6;
}

.feature-list li::before {
    content: "→";
    position: absolute;
    left: 0;
    color: #00d4ff;
    font-weight: bold;
}

.feature-list li {
    padding: var(--spacing-xs) var(--spacing-sm) var(--spacing-xs) 2rem;
    margin-bottom: 0;
    background: var(--glass-bg);
    border-radius: var(--radius-sm);
    backdrop-filter: blur(10px);
    font-size: 1.0625rem;
    line-height: 1.5;
    position: relative;
}

.feature-list li::before {
    content: "•";
    font-size: 1.5rem;
    color: var(--accent-primary);
    font-weight: bold;
    position: absolute;
    left: 0.5rem;
    top: 0.125rem;
}

.feature-list li {
    padding: var(--spacing-sm) 0;
    color: var(--text-secondary);
    font-size: 1rem;
    display: flex;
    align-items: flex-start;
    gap: var(--spacing-md);
    line-height: 1.6;
}

.feature-list li i {
    color: var(--success);
    font-size: 1rem;
    margin-top: 0.25rem;
}

.cta-group {
    display: flex;
    gap: 20px;
    justify-content: center;
    margin-top: 40px;
    flex-wrap: wrap;
}

.cta-btn {
    padding: 15px 35px;
    border-radius: 12px;
    font-size: 1.1rem;
    font-weight: 600;
    text-decoration: none;
    transition: all 0.3s ease;
    display: inline-block;
}

.cta-btn.primary {
    background: linear-gradient(135deg, var(--future-primary), var(--future-secondary));
    color: white;
    box-shadow: 0 5px 20px rgba(102, 126, 234, 0.4);
}

.cta-btn.secondary {
    background: rgba(255, 255, 255, 0.1);
    color: var(--text-primary);
    border: 1px solid rgba(255, 255, 255, 0.2);
}

.control-panel {
    background: rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
    align-items: center;
}

.control-input {
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 6px;
    padding: 8px 12px;
    color: white;
    font-size: 14px;
    min-width: 150px;
}

.control-input:focus {
    outline: none;
    border-color: var(--future-primary);
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.2);
}

.legend-section h4 {
    color: rgba(255, 255, 255, 0.8);
    font-size: 14px;
    font-weight: 600;
    margin: 0 0 10px 0;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.node-detail-panel {
    position: fixed;
    right: 20px;
    top: 100px;
    width: 350px;
    max-height: 600px;
    background: rgba(30, 30, 46, 0.95);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
    z-index: 1000;
    overflow-y: auto;
}

.node-detail-panel {
        position: fixed;
        left: 20px;
        right: 20px;
        width: auto;
        top: auto;
        bottom: 20px;
        max-height: 50vh;
    }

.node-detail-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    padding-bottom: 15px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.node-detail-header h3 {
    color: white;
    font-size: 18px;
    font-weight: 600;
    margin: 0;
}

.btn-close {
    background: rgba(255, 255, 255, 0.1);
    border: none;
    color: white;
    font-size: 24px;
    width: 30px;
    height: 30px;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
}

.gantt-control-panel {
    background: rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
    align-items: center;
}

.gantt-wrapper {
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 30px;
    margin-bottom: 20px;
    overflow-x: auto;
}

.task-detail-panel {
    position: fixed;
    right: 20px;
    top: 100px;
    width: 350px;
    max-height: 600px;
    background: rgba(30, 30, 46, 0.95);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
    z-index: 1000;
    overflow-y: auto;
}

.task-detail-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    padding-bottom: 15px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.task-detail-header h3 {
    color: white;
    font-size: 18px;
    font-weight: 600;
    margin: 0;
}

.section-title {
    color: white;
    font-size: 32px;
    font-weight: 700;
    text-align: center;
    margin-bottom: 20px;
}

.section-title {
    font-size: 2.5rem;
    text-align: center;
    margin-bottom: 3rem;
    color: var(--text-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--spacing-sm); /* Tight icon-title coupling */
}

.architecture-layer h4 {
    color: var(--future-accent);
    font-size: 18px;
    font-weight: 600;
    margin: 0 0 12px 0;
}

.architecture-layer li {
    color: rgba(255, 255, 255, 0.8);
    font-size: 14px;
    padding: 6px 0 6px 20px;
    position: relative;
}

.architecture-layer li::before {
    content: "•";
    position: absolute;
    left: 0;
    color: var(--future-primary);
}

.architecture-stats .stat {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 8px;
    padding: 15px;
    text-align: center;
}

.phase-card {
    background: rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 25px;
}

.phase-card {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    padding: var(--spacing-lg);
    text-align: center;
    position: relative;
    backdrop-filter: blur(10px);
    transition: all var(--transition-base);
}

.phase-card:hover {
    border-color: var(--accent-primary);
    transform: translateY(-4px);
    box-shadow: var(--glow);
}

.phase-card:hover {
        transform: none; /* Disable hover lift on mobile */
    }

.phase-card {
        backdrop-filter: blur(8px); /* Reduce blur for performance */
    }

.phase-number {
    width: 50px;
    height: 50px;
    background: linear-gradient(135deg, var(--future-primary), var(--future-secondary));
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 24px;
    font-weight: 700;
}

.phase-number {
    position: absolute;
    top: -12px;
    left: 50%;
    transform: translateX(-50%);
    width: 24px;
    height: 24px;
    background: var(--accent-primary);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 700;
    color: #000;
}

.phase-title {
    color: white;
    font-size: 20px;
    font-weight: 600;
    margin: 0;
    flex-grow: 1;
}

.phase-title {
    font-size: 1.125rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: var(--spacing-xs);
}

.phase-content h4 {
    color: var(--future-accent);
    font-size: 16px;
    font-weight: 600;
    margin: 15px 0 10px 0;
}

.phase-content li {
    color: rgba(255, 255, 255, 0.8);
    font-size: 14px;
    padding: 5px 0 5px 20px;
    position: relative;
}

.phase-content li::before {
    content: "✓";
    position: absolute;
    left: 0;
    color: var(--future-success);
}

.business-card {
    background: rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 30px;
}

.business-card h3 {
    color: white;
    font-size: 24px;
    font-weight: 600;
    margin: 0 0 25px 0;
}

.cost-row {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 15px;
    padding: 12px 15px;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 6px;
    font-size: 14px;
}

.benefit-text h4 {
    color: white;
    font-size: 18px;
    font-weight: 600;
    margin: 0 0 8px 0;
}

.benefit-text p {
    color: rgba(255, 255, 255, 0.8);
    font-size: 14px;
    line-height: 1.6;
    margin: 0;
}

.risk-item h4 {
    color: white;
    font-size: 18px;
    font-weight: 600;
    margin: 0;
}

.risk-item p {
    color: rgba(255, 255, 255, 0.8);
    font-size: 14px;
    line-height: 1.6;
    margin: 8px 0;
}

.metrics-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    margin: var(--spacing-xl) 0;
}

.metric-card {
    background: rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 30px;
    text-align: center;
}

.metric-card {
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    padding: var(--spacing-xl);
    text-align: center;
    transition: all var(--transition-base);
    box-shadow: var(--shadow);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--spacing-md);
}

.metric-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
    border-color: rgba(0, 212, 255, 0.3);
}

