    z-index: 1;
}

.glass-card:hover {
    backdrop-filter: blur(var(--glass-blur-lg)) saturate(200%);
    -webkit-backdrop-filter: blur(var(--glass-blur-lg)) saturate(200%);
    transform: translateY(-4px) scale(1.01);
    box-shadow: var(--shadow-glass-hover);
}

.glass-card::after {
    content: '';
    position: absolute;
    inset: -2px;
