.story-content {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 2rem 4rem;
    margin-left: calc(250px + 6rem); /* Account for sidebar */
    position: relative; /* Ensure proper stacking context */
    z-index: 20; /* Higher than sidebar to appear on top */
    background: var(--bg-primary); /* Ensure opaque background */
}

.story-chapter {
    margin-bottom: 4rem;
    scroll-margin-top: 100px; /* Account for fixed header */
}

.chapter-title {
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 2rem;
    border-bottom: 2px solid var(--accent-primary);
    padding-bottom: 1rem;
}

.story-text p {
        margin-bottom: 0.5cm;
        text-align: justify;
        widows: 3;
        orphans: 3;
    }

.story-text code {
    background: rgba(0, 212, 255, 0.1);
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
    font-family: 'Source Code Pro', monospace;
    font-size: 0.95em;
}

.story-text .time-check {
    color: var(--text-muted);
    font-family: 'Source Code Pro', monospace;
    font-size: 0.95rem;
}

.story-text .eureka-moment {
    font-size: 1.21rem !important;
    font-weight: 600;
    color: var(--accent-primary);
    display: inline-block;
    animation: glow 2s ease-in-out infinite;
}

.chapter-image-comic {
        max-width: 100%;
        margin: 0.5cm 0;
        border: 2pt solid #000 !important;
        page-break-inside: avoid;
    }

.chapter-image-comic img {
        max-width: 100%;
        height: auto;
        filter: grayscale(100%) contrast(1.2);
    }

.chapter-image-comic {
    margin: 2rem auto;
    max-width: 800px;
    border: 3px solid #000;
    background: #fff;
    box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.3), 0 0 20px rgba(0, 0, 0, 0.1);
    border-radius: 4px;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.chapter-image-comic img {
    width: 100%;
    height: auto;
    display: block;
    background: #fff;
    /* Filter for black & white cartoon aesthetic */
    filter: contrast(1.1) brightness(1.05);
}

.image-caption-comic {
        font-size: 10pt;
        text-align: center;
        padding: 0.25cm;
        background: #f5f5f5 !important;
        color: #333 !important;
        border-top: 1pt solid #000;
    }

.image-caption-comic {
    text-align: center;
    font-size: 0.875rem;
    color: #333;
    padding: 0.75rem;
    background: #f5f5f5;
    font-style: italic;
    border-top: 2px solid #000;
}

.technical-callout {
        margin: 0.5cm 0;
        padding: 0.5cm;
        border: 1pt solid #000 !important;
        border-left: 4pt solid #000 !important;
        page-break-inside: avoid;
        background: #f9f9f9 !important;
    }

.technical-callout img {
        max-width: 100%;
        border: 1pt solid #000 !important;
        margin: 0.25cm 0;
        filter: grayscale(100%) contrast(1.1);
    }

.technical-callout {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-left: 4px solid var(--accent-primary);
    border-radius: 12px;
    padding: 2rem;
    margin: 3rem 0;
    backdrop-filter: blur(12px);
    transition: all 0.3s ease;
}

.technical-callout h3 {
    color: var(--accent-primary);
    margin-bottom: 1rem;
    font-size: 1.25rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.technical-callout img {
    width: 100%;
    height: auto;
    border: 1px solid var(--accent-primary);
    background: rgba(0, 212, 255, 0.05);
    border-radius: 8px;
    margin: 1rem 0;
    box-shadow: 0 4px 20px rgba(0, 212, 255, 0.1);
    transition: transform 0.2s ease;
}

.coffee-counter {
        margin: 1cm 0;
        padding: 0.5cm;
        border: 2pt solid #000;
        background: #f9f9f9 !important;
        page-break-inside: avoid;
    }

.mug-note {
        font-size: 10pt;
        font-style: italic;
        text-align: center;
        color: #666 !important;
    }

.print-toc h2 {
        font-size: 18pt;
        margin-bottom: 0.5cm;
        border-bottom: 2pt solid #000;
        padding-bottom: 0.25cm;
    }

.story-logo-link {
    display: inline-block;
    margin-bottom: 2rem;
    transition: transform 0.3s ease;
}

.story-toc {
    position: fixed;
    left: 2rem;
    top: 120px;
    width: 250px;
    max-height: calc(100vh - 160px);
    overflow-y: auto;
    background: var(--glass-bg);
    backdrop-filter: blur(12px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 1.5rem;
    box-shadow: var(--shadow-lg);
    z-index: 10; /* Reduced from 100 to allow content to sit on top */
}

.story-toc h3 {
    font-size: 1rem;
    font-weight: 600;
    color: var(--accent-primary);
    margin-bottom: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.story-toc {
        display: none; /* Hide sidebar on mobile */
    }

.toc-link {
    color: var(--text-secondary);
    text-decoration: none;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    font-size: 0.875rem;
    transition: all 0.2s ease;
    border-left: 3px solid transparent;
}

.toc-link:hover {
    background: rgba(0, 212, 255, 0.1);
    color: var(--text-primary);
    border-left-color: var(--accent-primary);
}

.toc-link.active {
    background: rgba(0, 212, 255, 0.15);
    color: var(--accent-primary);
    font-weight: 500;
    border-left-color: var(--accent-primary);
}

.story-image-inline {
    margin: 2.5rem auto;
    max-width: 700px;
    border: 3px solid #000;
    background: #fff;
    box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.3), 0 0 20px rgba(0, 0, 0, 0.1);
    border-radius: 4px;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.story-image-inline img {
    width: 100%;
    height: auto;
    display: block;
    background: #fff;
    filter: contrast(1.1) brightness(1.05);
}

.story-image-inline .image-caption {
    text-align: center;
    font-size: 0.875rem;
    color: #333;
    padding: 0.75rem;
    background: #f5f5f5;
    font-style: italic;
    border-top: 2px solid #000;
}

.whiteboard-note {
    background: rgba(255, 255, 255, 0.05);
    border: 2px dashed rgba(0, 212, 255, 0.3);
    padding: 1.5rem;
    margin: 2rem 0;
    font-family: 'Source Code Pro', monospace;
    font-size: 1rem;
    color: rgba(0, 212, 255, 0.9);
    border-radius: 8px;
    position: relative;
}

.whiteboard-note::before {
    content: '📝';
    position: absolute;
    top: -12px;
    left: 12px;
    background: var(--bg-primary);
    padding: 0 8px;
    font-size: 1.2rem;
}

.callout-link {
    color: var(--accent-primary);
    text-decoration: none;
    font-weight: 500;
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    transition: all 0.2s ease;
}

.story-disclaimer {
    background: var(--glass-bg);
    border: 2px solid rgba(255, 165, 0, 0.3);
    border-radius: 12px;
    padding: 2rem;
    margin: 4rem 0;
    backdrop-filter: blur(12px);
}

.metrics-column {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 1.5rem;
    backdrop-filter: blur(12px);
}

.metrics-magic {
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.1), rgba(123, 97, 255, 0.1));
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 2rem;
    text-align: center;
}

.story-credits {
    text-align: center;
    padding: 3rem 0;
    border-top: 1px solid var(--glass-border);
    margin-top: 4rem;
}

.back-to-top {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    width: 50px;
    height: 50px;
    border-radius: 50%;
    background: var(--accent-primary);
    color: var(--bg-primary);
    border: none;
    font-size: 1.5rem;
    cursor: pointer;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
    z-index: 1000;
    box-shadow: var(--shadow-lg);
}

.chapter-navigation {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 3rem 0;
    padding: 2rem;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 16px;
    backdrop-filter: blur(10px);
}

.chapter-nav-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.5rem;
    background: linear-gradient(135deg, rgba(0, 255, 255, 0.1), rgba(0, 150, 255, 0.1));
    border: 1px solid rgba(0, 255, 255, 0.2);
    border-radius: 12px;
    color: #00ffff;
    text-decoration: none;
    font-weight: 500;
    font-size: 0.95rem;
    transition: all 0.3s ease;
    backdrop-filter: blur(5px);
}

.chapter-nav-btn:hover {
    background: linear-gradient(135deg, rgba(0, 255, 255, 0.2), rgba(0, 150, 255, 0.2));
    border-color: rgba(0, 255, 255, 0.4);
    transform: translateY(-2px);
    box-shadow: 0 8px 20px rgba(0, 255, 255, 0.2);
}

.chapter-nav-btn .nav-label {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0.25rem;
}

.chapter-nav-btn .nav-direction {
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.6);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.character-reference {
    position: fixed;
    right: 2rem;
    top: 50%;
    transform: translateY(-50%);
    width: 280px;
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    padding: 1.5rem;
    backdrop-filter: blur(12px);
    box-shadow: var(--shadow-lg);
    z-index: 100;
    max-height: 80vh;
    overflow-y: auto;
}

.character-reference h3 {
    font-size: 1.125rem;
    color: var(--accent-primary);
    margin-bottom: 1rem;
    padding-bottom: 0.75rem;
    border-bottom: 2px solid var(--glass-border);
}

.character-name {
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 0.5rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.character-name::before {
    content: "";
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--accent-primary);
    box-shadow: 0 0 8px var(--accent-primary);
}

.social-share {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    z-index: 100;
}

.share-btn {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    color: var(--text-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
    backdrop-filter: blur(10px);
    text-decoration: none;
    font-size: 1.25rem;
}

.share-btn:hover {
    transform: scale(1.1);
    box-shadow: 0 0 20px rgba(0, 212, 255, 0.3);
    border-color: var(--accent-primary);
}

.whiteboard-panel {
    background: linear-gradient(135deg, #f5f5f0 0%, #e8e8e0 100%);
    border: 3px solid #8b7355;
    border-radius: 8px;
    padding: 2rem;
    margin: 2rem 0;
    position: relative;
    box-shadow: 
        inset 0 0 20px rgba(0, 0, 0, 0.05),
        0 4px 12px rgba(0, 0, 0, 0.15);
}

.whiteboard-panel::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: repeating-linear-gradient(
        90deg,
        transparent,
        transparent 2px,
        rgba(139, 115, 85, 0.03) 2px,
        rgba(139, 115, 85, 0.03) 4px
    );
    opacity: 0.5;
    pointer-events: none;
    border-radius: 8px;
}

.whiteboard-panel code {
    font-family: 'Caveat', cursive;
    font-size: 1.4rem;
    line-height: 1.8;
    color: #2c2c2c;
    background: transparent;
    border: none;
    white-space: pre-wrap;
}

.whiteboard-panel .highlight {
    background: rgba(255, 255, 0, 0.3);  /* Yellow highlighter */
    padding: 0 4px;
    border-radius: 2px;
}

.narrator {
    padding: 1.5rem;
    margin: 1.5rem 0;
    border-radius: 12px;
    position: relative;
    font-style: italic;
}

.narrator.asif {
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.1) 0%, rgba(0, 102, 204, 0.1) 100%);
    border-left: 4px solid #00d4ff;
    color: #00d4ff;
}

.narrator.miss-g {
    background: linear-gradient(135deg, rgba(255, 0, 255, 0.1) 0%, rgba(255, 102, 179, 0.1) 100%);
    border-left: 4px solid #ff00ff;
    color: #ff66b3;
}

.narrator::before {
    position: absolute;
    top: -10px;
    left: 20px;
    font-size: 0.8rem;
    padding: 2px 8px;
    border-radius: 4px;
    font-style: normal;
    font-weight: 600;
}

.comparison-section {
    background: rgba(36, 41, 68, 0.9); /* Slightly more opaque for better contrast */
    border: 1px solid var(--sts-glass-border);
    border-radius: 20px;
    padding: 2rem 2.5rem;
    margin-bottom: 2.5rem;
    backdrop-filter: blur(10px);
}

.section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.section-header h3 {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 1.5rem;
    font-weight: 700;
    color: #fff;
    margin: 0;
}

.language-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.875rem;
    font-weight: 600;
    padding: 0.375rem 0.875rem;
    border-radius: 6px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.language-badge.csharp {
    background: rgba(104, 33, 122, 0.25);
    color: #c084fc;
    border: 1px solid rgba(156, 39, 176, 0.4);
}

.language-badge.typescript {
    background: rgba(49, 120, 198, 0.25);
    color: #60a5fa;
    border: 1px solid rgba(49, 120, 198, 0.4);
}

.language-badge.angular {
    background: rgba(221, 0, 49, 0.2);
    color: #f87171;
    border: 1px solid rgba(221, 0, 49, 0.4);
}

.language-badge.sql {
    background: rgba(0, 150, 199, 0.25);
    color: #67e8f9;
    border: 1px solid rgba(0, 150, 199, 0.4);
}

.language-badge.sql::before {
    content: "\f1c0";
    font-family: 'Font Awesome 6 Free';
    font-weight: 900;
    font-size: 0.875rem;
}

.language-badge.javascript {
    background: rgba(247, 223, 30, 0.2);
    color: #fde047;
    border: 1px solid rgba(247, 223, 30, 0.4);
}

.sts-hero .hero-badge {
    display: inline-block;
    padding: 0.5rem 1.5rem;
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.2), rgba(123, 97, 255, 0.2));
    border: 1px solid rgba(0, 212, 255, 0.4);
    border-radius: 50px;
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--sts-accent);
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 1.5rem;
    box-shadow: var(--sts-glow);
}

.sts-hero h1 {
    font-size: 3rem;
    font-weight: 800;
    line-height: 1.1;
    margin-bottom: 1rem;
    color: #fff;
    text-shadow: 0 0 30px rgba(0, 212, 255, 0.5);
}

.sts-hero .hero-subtitle {
    font-size: 1.125rem;
    color: rgba(255, 255, 255, 0.7);
    max-width: 600px;
    margin: 0 auto 2rem;
}

.sts-metrics {
    background: rgba(0, 0, 0, 0.3);
    padding: 1.5rem;
    border-radius: 12px;
    margin: 1.5rem 0;
    overflow-x: auto;
    display: flex;
    justify-content: center;
    gap: 1.5rem;
    flex-wrap: nowrap; /* CRITICAL: Single line only */
}

.sts-metrics .metric-card {
    background: var(--sts-glass-bg);
    border: 1px solid var(--sts-glass-border);
    border-radius: 12px;
    padding: 1rem 1.5rem;
    min-width: 120px;
    flex-shrink: 0; /* Prevent cards from shrinking */
    text-align: center;
    backdrop-filter: blur(10px);
    transition: all 0.3s ease;
}

.sts-metrics .metric-card.accent {
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.15), rgba(123, 97, 255, 0.15));
    border-color: rgba(0, 212, 255, 0.3);
}

.sts-metrics .metric-value {
    display: block;
    font-size: 2rem;
    font-weight: 800;
    color: #fff;
    line-height: 1.2;
}

.sts-metrics .metric-label {
    display: block;
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.6);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-top: 0.25rem;
}

.sts-metrics {
        gap: 0.75rem;
        padding: 1rem;
        justify-content: flex-start; /* Left-align on mobile for better scroll UX */
    }

.sts-education .education-card {
    background: var(--sts-glass-bg);
    border: 1px solid var(--sts-glass-border);
    border-radius: 16px;
    padding: 2rem;
    backdrop-filter: blur(10px);
}

.sts-education h3 {
    font-size: 1.25rem;
    color: #fff;
    margin-bottom: 1.5rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.sts-issue-card {
    background: var(--sts-glass-bg);
    border: 1px solid var(--sts-glass-border);
    border-radius: 20px;
    padding: 2rem;
    margin-bottom: 2rem;
    backdrop-filter: blur(10px);
    transition: all 0.3s ease;
}

.refactor-explanation {
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.08), rgba(123, 97, 255, 0.08));
    border: 1px solid rgba(0, 212, 255, 0.2);
    border-radius: 12px;
    padding: 1.25rem 1.5rem;
    margin-bottom: 1.5rem;
}

.refactor-explanation h4 {
    font-size: 0.9375rem;
    color: var(--sts-accent);
    margin-bottom: 0.75rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.refactor-explanation p {
    font-size: 0.875rem;
    color: rgba(255, 255, 255, 0.85);
    line-height: 1.6;
    margin: 0;
}

.refactor-explanation .why-matters {
    margin-top: 0.75rem;
    padding-top: 0.75rem;
    border-top: 1px solid rgba(0, 212, 255, 0.15);
    font-size: 0.8125rem;
    color: rgba(255, 255, 255, 0.7);
}

.refactor-explanation ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    margin-top: 0.75rem;
}

.refactor-explanation li {
    font-size: 0.875rem;
    color: rgba(255, 255, 255, 0.85);
    padding: 1rem;
    border-radius: 8px;
    line-height: 1.6;
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.refactor-explanation li:nth-child(1) {
    background: rgba(0, 150, 199, 0.1);
    border: 1px solid rgba(0, 150, 199, 0.3);
}

.refactor-explanation li:nth-child(1):hover {
    background: rgba(0, 150, 199, 0.15);
    border-color: rgba(0, 150, 199, 0.5);
    transform: translateY(-2px);
}

.refactor-explanation li:nth-child(2) {
    background: rgba(16, 185, 129, 0.1);
    border: 1px solid rgba(16, 185, 129, 0.3);
}

.refactor-explanation li:nth-child(2):hover {
    background: rgba(16, 185, 129, 0.15);
    border-color: rgba(16, 185, 129, 0.5);
    transform: translateY(-2px);
}

.refactor-explanation li:nth-child(3) {
    background: rgba(139, 92, 246, 0.1);
    border: 1px solid rgba(139, 92, 246, 0.3);
}

.refactor-explanation li:nth-child(3):hover {
    background: rgba(139, 92, 246, 0.15);
    border-color: rgba(139, 92, 246, 0.5);
    transform: translateY(-2px);
}

.refactor-explanation li strong {
    display: block;
    font-size: 0.8125rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.25rem;
}

.transform-panels {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    gap: 1rem;
    align-items: stretch;
    margin-bottom: 1.5rem;
}

.transform-arrow {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 0 0.5rem;
    color: var(--sts-accent);
}

.transform-arrow span {
    font-size: 0.625rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-top: 0.25rem;
}

.panel {
    background: rgba(0, 0, 0, 0.9); /* Darker black background for code panels */
    border-radius: 12px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.panel pre {
    margin: 0;
    padding: 1.25rem; /* Increased padding for better spacing */
    flex: 1;
    overflow-x: auto;
    font-size: 0.9375rem; /* Increased for better readability */
    line-height: 1.6; /* Increased for better spacing */
    background: #0a0a0a; /* Slightly lighter than pure black */
}

.panel pre.auto-height {
    overflow-y: visible;
    height: auto;
    min-height: 200px;
}

.panel pre.fixed-height {
    overflow-y: auto;
    height: 600px; /* Desktop default - overridden by JS */
    min-height: 200px;
}

.panel pre.fixed-height {
        height: 400px; /* Mobile default - overridden by JS */
    }

.panel code {
    font-family: 'Courier New', 'Courier', monospace; /* Retro console font */
    font-size: 0.9375rem; /* Increased from 0.8125rem for better readability */
    line-height: 1.6; /* Increased for better readability */
    letter-spacing: 0.02em; /* Slight letter spacing for clarity */
}

.panel code.hljs {
    background: #000000 !important; /* Pure black - override all themes */
}

.comparison-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.5rem;
    align-items: stretch;
}

.fix-explanation {
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.1), rgba(123, 97, 255, 0.1));
    border: 1px solid rgba(0, 212, 255, 0.25);
    border-radius: 12px;
    padding: 1.25rem;
}

.fix-explanation h4 {
    font-size: 0.9375rem;
    color: var(--sts-accent);
    margin-bottom: 0.75rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.fix-explanation li {
    font-size: 0.875rem;
    color: rgba(255, 255, 255, 0.8);
    padding: 0.375rem 0;
    padding-left: 1.25rem;
    position: relative;
}

.fix-explanation li::before {
    content: '✓';
    position: absolute;
    left: 0;
    color: #86efac;
    font-weight: bold;
}

.fix-explanation code {
    background: rgba(0, 0, 0, 0.3);
    padding: 0.125rem 0.375rem;
    border-radius: 4px;
    font-size: 0.8125rem;
    color: #fde047;
}

.sts-best-practices h2 {
    font-size: 1.5rem;
    color: #fff;
    text-align: center;
    margin-bottom: 2rem;
}

.practice-card {
    background: var(--sts-glass-bg);
    border: 1px solid var(--sts-glass-border);
    border-radius: 16px;
    padding: 1.5rem;
    text-align: center;
    transition: all 0.3s ease;
    backdrop-filter: blur(10px);
}

.practice-card:hover {
    background: rgba(0, 212, 255, 0.08);
    border-color: rgba(0, 212, 255, 0.3);
    transform: translateY(-2px);
    box-shadow: var(--sts-glow);
}

.practice-card p {
    font-size: 0.875rem;
    color: rgba(255, 255, 255, 0.6);
    line-height: 1.5;
    margin-bottom: 0.75rem;
}

.practice-card code {
    display: inline-block;
    background: rgba(0, 0, 0, 0.4);
    padding: 0.375rem 0.75rem;
    border-radius: 6px;
    font-size: 0.75rem;
    color: #fde047;
}

.practice-icon {
    width: 48px;
    height: 48px;
    margin: 0 auto 1rem;
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.2), rgba(123, 97, 255, 0.2));
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.sts-nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 2rem 0;
    margin-top: 2rem;
    border-top: 1px solid var(--sts-glass-border);
}

.sts-nav a {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    background: var(--sts-glass-bg);
    border: 1px solid var(--sts-glass-border);
    border-radius: 8px;
    color: rgba(255, 255, 255, 0.8);
    text-decoration: none;
    font-size: 0.875rem;
    transition: all 0.2s ease;
    backdrop-filter: blur(10px);
}

.sts-nav a:hover {
    background: rgba(0, 212, 255, 0.15);
    border-color: rgba(0, 212, 255, 0.4);
    color: #fff;
    box-shadow: var(--sts-glow);
}

.sts-nav .nav-hub {
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.15), rgba(123, 97, 255, 0.15));
    border-color: rgba(0, 212, 255, 0.3);
}

.flaw-preview li {
    font-size: 0.8125rem;
    color: rgba(255, 255, 255, 0.6);
    padding: 0.25rem 0;
    padding-left: 1rem;
    position: relative;
}

.flaw-preview li::before {
    content: '→';
    position: absolute;
    left: 0;
    color: rgba(255, 255, 255, 0.4);
}
